import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import { mockBoundingClientRect } from "../../lib/tests/testUtils";
import * as stories from "./Slider.stories";
import Slider, { RangeSlider } from "./Slider";

const { Labelling } = composeStories(stories) as any;

describe("Slider", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Labelling />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Slider data-testid="rangeslider" />);
    expect(screen.getByTestId("rangeslider")).toBeTruthy();
  });

  it("is retrocompatible with deprecated names", () => {
    render(<RangeSlider />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(/AIRBUS-DS/);
  });

  it("display warnings with invalid props", () => {
    render(<Slider defaultValue={[0, 110]} min={10} max={100} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(
      /expects the `defaultValue` prop to be contained in `min` and `max` range/
    );

    render(<Slider step={-10} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(2);
    expect(consoleSpy.warn.mock.calls[1][0]).toMatch(
      /expects the `step` prop to be greater than zero/
    );

    render(<Slider step={3} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(3);
    expect(consoleSpy.warn.mock.calls[2][0]).toMatch(
      /expects the `min` and `max` range to be evenly divisible by the `step` prop/
    );

    render(<Slider minDistance={-1} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(4);
    expect(consoleSpy.warn.mock.calls[3][0]).toMatch(
      /expects the `minDistance` prop to be greater than zero/
    );

    render(<Slider minDistance={5} step={3} max={9} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(5);
    expect(consoleSpy.warn.mock.calls[4][0]).toMatch(
      /expects the `minDistance` prop to be evenly divisible by the `step` prop/
    );

    // @ts-expect-error
    render(<Slider size={1} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(6);
    expect(consoleSpy.warn.mock.calls[5][0]).toMatch(
      /expects the `size` prop to either be 'medium' or 'large'/
    );
  });

  it("allow keyboard navigation", async () => {
    const callback = jest.fn();
    render(
      <Slider defaultValue={[0, 100]} step={10} onChange={callback} />
    );
    const sliders = screen.getAllByRole("slider");
    expect(sliders).toHaveLength(2);

    await userEvent.tab();
    expect(sliders[0]).toHaveFocus();
    fireEvent.keyDown(sliders[0], { key: "ArrowUp" });
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith([10, 100]);

    fireEvent.keyDown(sliders[0], { key: "ArrowUp" });
    fireEvent.keyDown(sliders[0], { key: "ArrowRight" });
    expect(callback).toHaveBeenCalledTimes(3);
    expect(callback).toHaveBeenLastCalledWith([30, 100]);

    fireEvent.keyDown(sliders[0], { key: "ArrowDown" });
    fireEvent.keyDown(sliders[0], { key: "ArrowLeft" });
    expect(callback).toHaveBeenCalledTimes(5);
    expect(callback).toHaveBeenLastCalledWith([10, 100]);

    fireEvent.keyDown(sliders[0], { key: "End" });
    expect(callback).toHaveBeenCalledTimes(6);
    expect(callback).toHaveBeenLastCalledWith([100, 100]);

    await userEvent.tab();
    expect(sliders[1]).toHaveFocus();
    fireEvent.keyDown(sliders[1], { key: "Home" });
    expect(callback).toHaveBeenCalledTimes(7);
    expect(callback).toHaveBeenLastCalledWith([0, 100]);
  });

  it("disabling range slider should work", () => {
    const callback = jest.fn();
    render(
      <Slider
        data-testid="rangeslider"
        defaultValue={[0, 100]}
        onChange={callback}
        disabled
      />
    );
    const root = screen.getByTestId("rangeslider");
    mockBoundingClientRect(root, { width: 1000 });
    fireEvent.mouseDown(root, { clientX: 100 });
    expect(callback).toHaveBeenCalledTimes(0);
  });

  it("allow clicking on track to move closest thumb", () => {
    const callback = jest.fn();
    render(
      <Slider
        data-testid="rangeslider"
        defaultValue={[0, 100]}
        step={10}
        onChange={callback}
      />
    );
    const root = screen.getByTestId("rangeslider");
    mockBoundingClientRect(root, { width: 1000 });
    fireEvent.mouseDown(root, { clientX: 100 });
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith([10, 100]);

    fireEvent.mouseDown(root, { clientX: 800 });
    expect(callback).toHaveBeenCalledTimes(2);
    expect(callback).toHaveBeenLastCalledWith([10, 80]);
  });
});
